/// The options of each control of `ProductListProductsArgsForm` that refers to
/// an item, by its path, under `choices`, the app's, which win where they name
/// the control: `ids` (Product). A control keeps its own when the caller may
/// not list the items, or more follow than a page holds.
pub async fn product_list_products_args_form_choices(cx: &Cx, form: &ProductListProductsArgsForm, choices: Choices) -> Choices {
    let _ = form;
    let mut found = Choices::new();
    if !named(&choices, "ids")
        && let Some(options) = product_target_choices(cx).await
    {
        found = found.with("ids", pairs(&options));
    }
    choices.or(found)
}

/// The labels of the values `OrderInputRecord`s show that refer to an item, by
/// their paths, under `choices`, the app's, which win where they name the
/// field: `lines.productId` (Product), `giftSku` (Product). One lookup a
/// target, for every record's values; a value no item has, or that the caller
/// may not list, shows as it is.
pub async fn order_input_labels(cx: &Cx, records: &[OrderInputRecord], choices: Choices) -> Choices {
    let json: Vec<Value> = records.iter().map(OrderInputRecord::to_wire).collect();
    let mut found = Choices::new();
    let sites = unnamed(&choices, &[("lines.productId", &["lines", "productId"])]);
    if !sites.is_empty() {
        let labels = product_target_labels(cx, &values_at(&json, &sites)).await;
        for (path, _) in sites {
            found = found.with(path, pairs(&labels));
        }
    }
    let sites = unnamed(&choices, &[("giftSku", &["giftSku"])]);
    if !sites.is_empty() {
        let labels = product_by_sku_target_labels(cx, &values_at(&json, &sites)).await;
        for (path, _) in sites {
            found = found.with(path, pairs(&labels));
        }
    }
    choices.or(found)
}

